export default function Component04OQueEInsegurancaAlimentar() {
  return (
    <button className="block cursor-pointer relative size-full" data-node-id="503:520" data-name="04 • O que é insegurança alimentar?">
      <img alt="" className="absolute block inset-0 max-w-none size-full" src={img04OQueEInsegurancaAlimentar} />
      <div className="absolute contents inset-[3.91%_89.86%_94.43%_3.33%]" data-node-id="503:522" data-name="Rubrica">
        <p className="[word-break:break-word] absolute font-['Archivo:Bold'] font-bold inset-[3.91%_89.86%_94.43%_3.33%] leading-[normal] text-[#ad6c49] text-[16px] text-left whitespace-nowrap" data-node-id="503:523" style={{ fontVariationSettings: '"wdth" 100' }}>
          CONCEITOS
        </p>
      </div>
      <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal inset-[33.5%_67.78%_13.96%_3.33%] leading-[0] text-[#153b2e] text-[0px] text-left" data-node-id="503:531" style={{ fontVariationSettings: '"wdth" 100' }}>
        <span className="font-['Libre_Baskerville:Regular'] leading-[64px] text-[64px]">A</span>
        <span className="leading-[28px] text-[20px]">{` fome pode ser compreendida por seus aspectos biológico e social. Ela ocorre quando uma pessoa não consegue consumir alimentos em quantidade suficiente para atender às necessidades do organismo. Não existe uma quantidade universal de calorias que determine se uma pessoa está passando fome. As necessidades energéticas variam conforme idade, sexo, tamanho corporal e nível de atividade física. Por isso, a FAO utiliza uma metodologia específica para estimar as necessidades da população analisada (FAO, s.d.-a). A desnutrição não deve ser confundida com fome ou subalimentação. Enquanto a subalimentação se refere principalmente à quantidade insuficiente de energia alimentar, a desnutrição é mais ampla e pode envolver deficiências de nutrientes, crescimento`}</span>
      </p>
      <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal inset-[31.25%_35.56%_14.06%_35.56%] leading-[28px] text-[#153b2e] text-[20px] text-left" data-node-id="503:532" style={{ fontVariationSettings: '"wdth" 100' }}>
        inadequado e emagrecimento extremo. A insegurança alimentar tem um significado mais amplo do que a fome. Uma pessoa pode consumir alimentos todos os dias e ainda não conseguir manter uma alimentação adequada, variada e nutritiva. A falta de garantia de acesso regular à alimentação pode se manifestar antes da privação mais grave. Isso acontece quando há preocupação de que a comida não seja suficiente até o fim do mês, quando a família diminui a variedade da alimentação ou reduz a quantidade de alimentos por falta de recursos. O acesso à alimentação depende de renda, emprego, preços dos alimentos e possibilidade de chegar aos locais onde eles são vendidos. Assim, a insegurança alimentar constitui também um problema social, relacionado às condições de vida e à distribuição de recursos dentro da sociedade.
      </p>
      <p className="[word-break:break-word] absolute font-['Libre_Baskerville:Regular'] font-normal inset-[7.81%_3.33%_86.52%_3.33%] leading-[58px] text-[#153b2e] text-[48px] text-left" data-node-id="503:533">
        O que é insegurança alimentar?
      </p>
      <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal inset-[15.23%_3.33%_81.45%_3.33%] leading-[33.6px] text-[#153b2e] text-[24px] text-left" data-node-id="503:534" style={{ fontVariationSettings: '"wdth" 100' }}>
        Insegurança alimentar é mais ampla que a privação extrema. Entender as diferenças evita leituras apressadas.
      </p>
      <p className="[word-break:break-word] absolute font-['Archivo:Regular'] font-normal inset-[88.87%_51.94%_8.89%_3.33%] leading-[22.4px] text-[#67786b] text-[16px] text-left" data-node-id="503:535" style={{ fontVariationSettings: '"wdth" 100' }}>
        Fontes: FAO, conceitos de fome e insegurança alimentar; IBGE, PNAD Contínua 2024, p. 1.
      </p>
      <div className="[word-break:break-word] absolute border border-[var(--margem-cor-linha,#c9cdbb)] border-solid content-stretch flex gap-[24px] h-[76px] items-start leading-[24px] left-[48px] p-[12px] rounded-[4px] text-[16px] text-left top-[212px]" data-node-id="503:536" data-name="Mini glossário • nesta página">
        <p className="font-['Archivo:Bold'] font-bold relative shrink-0 text-[color:var(----cor-terracota,#ad6c49)] w-[140px]" data-node-id="I503:536;50:97" style={{ fontVariationSettings: '"wdth" 100' }}>
          GLOSSÁRIO
        </p>
        <p className="font-['Archivo:Regular'] font-normal relative shrink-0 text-[color:var(--margem-cor-verde,#153b2e)] w-[1156px]" data-node-id="I503:536;50:98" style={{ fontVariationSettings: '"wdth" 100' }}>
          FAO • Organização das Nações Unidas para a Alimentação e a Agricultura. EBIA • Escala Brasileira de Insegurança Alimentar. IBGE • Instituto Brasileiro de Geografia e Estatística. PNAD • Pesquisa Nacional por Amostra de Domicílios.
        </p>
      </div>
      <EditorialPainelEbiaInterativo className="absolute bg-[var(----cor-terracota,#ad6c49)] h-[556px] left-[976px] overflow-clip top-[320px] w-[416px]" />
    </button>
  );
}
